<template>
  <section class="session-capture" aria-label="Session recording">
    <header><div><h2>Session recording</h2><p>Capture this session, then review its Session Narrative before using it in a note.</p></div><button type="button" @click="$emit('close')" aria-label="Close session recording">×</button></header>
    <p class="privacy">Recording is optional. Audio is sent through the approved private transcription service and deleted after transcription. Transcript and narrative are encrypted. Spoken identifiers may be heard by that approved processor; Narriva receives privacy-screened text.</p>
    <p v-if="error" role="alert">{{ error }}</p><p v-if="hint" role="status">{{ hint }}</p>
    <p v-if="loading" role="status">Checking this session’s recording permissions…</p>
    <template v-else-if="state">
      <p v-if="!state.configured" class="notice">Secure transcription is not configured for this workspace. Recording stays off; you can continue the appointment and write the note manually.</p>
      <button v-if="!recording" type="button" @click="setup" :disabled="busy || !state.configured">Set up recording for this session</button>
      <template v-else>
        <p v-if="state.participantReviewNeeded" role="alert">The appointment participants changed. <button type="button" @click="setup" :disabled="busy">Refresh required participant waivers</button></p><h3>Participant waivers</h3><p>Every recorded adult needs their own waiver. An authorized signer must consent for each recorded minor. Scheduled participants are included automatically.</p>
        <article v-for="participant in state.participants" :key="participant.id" class="participant">
          <div><strong>{{ participant.name }}</strong><small>{{ participant.requiresGuardian ? 'Authorized signer required' : 'Participant waiver' }}</small><span :class="['consent-state', { signed: participant.consented }]">{{ participant.consented ? 'Signed waiver on file' : participant.taskPending ? 'Awaiting portal signature' : 'Signature needed' }}</span></div>
          <div class="participant-actions">
            <button v-if="participant.consented" type="button" @click="withdraw(participant)" :disabled="busy || capturing">Withdraw waiver</button>
            <template v-else><button type="button" @click="openWaiver(participant)" :disabled="busy || capturing || !templateId">Sign here / assign in portal</button></template>
            <button v-if="participant.canRemove" type="button" @click="remove(participant)" :disabled="busy || capturing">Remove added participant</button>
          </div>
        </article>
        <label>Recording waiver<select v-model="templateId" :disabled="capturing"><option value="">Choose the current waiver</option><option v-for="t in state.templates" :key="t.id" :value="t.id">{{ t.name }} · v{{ t.version || 1 }}</option></select></label>
        <p v-if="!state.templates.length">A practice administrator must add an audio recording waiver to the document library.</p>
        <form class="add-participant" @submit.prevent="addParticipant"><h4>Another person will be recorded</h4><label>Name<input v-model="additionalName" maxlength="255" required :disabled="capturing"></label><label>Participant<select v-model="additionalType" :disabled="capturing"><option value="adult">Adult</option><option value="minor">Minor</option></select></label><p v-if="additionalType === 'minor'">Add the minor as an actual session client first so their verified guardian can consent. Then refresh this session’s required waivers.</p><button :disabled="busy || capturing || !additionalName.trim() || additionalType === 'minor'">Add participant</button></form>
        <div v-if="agreement" class="waiver">
          <header><h3>Review and sign the waiver</h3><button type="button" @click="closeWaiver" aria-label="Close waiver">×</button></header>
          <iframe :src="agreementPdf || undefined" :srcdoc="agreementPdf ? undefined : agreement.html" title="Recording waiver" sandbox="" />
          <div v-if="selectedParticipant?.signers?.length" class="portal-assignment"><label>Authorized portal recipient<select v-model="signerUserId"><option value="">Choose the client or guardian</option><option v-for="s in selectedParticipant.signers" :key="s.userId" :value="s.userId">{{ s.name }} · {{ s.relationship === 'self' ? 'Client' : 'Authorized guardian' }}</option></select></label><button type="button" @click="assignPortal" :disabled="busy || !signerUserId">Assign waiver in portal</button></div>
          <form @submit.prevent="signHere"><h4>Sign here on this device</h4><p>Hand the device to the actual signer. Their finger signature is stored with the waiver; the clinician is recorded as the presenter, not as the client’s signer.</p>
            <label v-if="selectedParticipant?.clientId && relationship !== 'self'">Verified authorized signer<select v-model="guardianSignerUserId" @change="selectGuardian" required><option value="">Choose the verified guardian / representative</option><option v-for="s in guardianChoices" :key="s.userId" :value="s.userId">{{ s.name }}</option></select></label><p v-if="selectedParticipant?.clientId && relationship !== 'self' && !guardianChoices.length" role="alert">Complete guardian authority verification on the client record first. A clinician checkbox cannot grant consent rights.</p><label>Signer’s full name<input v-model="signerName" autocomplete="off" required maxlength="255" :readonly="selectedParticipant?.clientId && relationship !== 'self'"></label>
            <label>I am signing as<select v-model="relationship"><option v-if="!selectedParticipant?.requiresGuardian" value="self">The recorded adult / client</option><option v-if="selectedParticipant?.clientId" value="parent">Verified authorized parent</option><option v-if="selectedParticipant?.clientId" value="legal_guardian">Verified legal guardian / representative</option></select></label>
            <label class="check"><input v-model="accepted" type="checkbox" required>I reviewed this waiver, agree to recording, and intend to sign it electronically.</label>
            <AdaptiveSignatureCapture v-model="signatureData" />
            <label class="check"><input v-model="authorityConfirmed" type="checkbox" required>Clinician: I verified the actual signer’s identity, presence and authority to consent for this participant.</label>
            <button :disabled="busy || !signatureData || !accepted || !authorityConfirmed || (selectedParticipant?.clientId && relationship !== 'self' && !guardianSignerUserId)">Sign and save to client documents</button>
          </form>
        </div>
        <fieldset v-if="!capturing"><legend>Approve recording for this session</legend><label class="check"><input v-model="allParticipantsListed" type="checkbox">Every person who will be audible is listed above; no other person will be recorded.</label><label class="check"><input v-model="authorityReviewed" type="checkbox">I reviewed the waivers and consent authority for these participants.</label><label class="check"><input v-model="providerAgrees" type="checkbox">I consent to recording my own participation and will pause if attendance or consent changes.</label><button type="button" @click="confirm" :disabled="busy || !allConsented || !allParticipantsListed || !authorityReviewed || !providerAgrees || !state.configured">Confirm session consent</button><span v-if="recording.confirmed" class="consent-state signed">This session is confirmed</span></fieldset>
        <div class="capture-controls"><strong role="status">{{ capturing ? '● Recording this session' : recording.paused ? 'Recording paused' : 'Recording off' }}</strong><button v-if="!capturing && recording.status !== 'completed'" type="button" @click="start" :disabled="busy || !state.ready">{{ recording.status === 'setup' ? 'Start recording' : 'Resume recording' }}</button><button v-if="capturing" type="button" @click="pause" :disabled="busy">Pause recording</button><button v-if="recording.status !== 'completed'" type="button" @click="finish" :disabled="busy || recording.status === 'setup'">Stop and prepare Session Narrative</button></div>
        <div v-if="narrative" class="narrative-review"><label>Session Narrative<textarea v-model="narrative" rows="12" @input="narrativeEdited = true" /></label><p>Review attribution, risk, interventions, responses and follow-up. Narriva does not add facts that were absent from the session.</p><button type="button" @click="useNarrative" :disabled="busy">Use this Session Narrative in the note</button></div>
      </template>
    </template>
  </section>
</template>
<script setup>
import {computed,onMounted,onBeforeUnmount,ref} from 'vue';
import AdaptiveSignatureCapture from '../adaptive-intake/AdaptiveSignatureCapture.vue';
import {meetingAudioWav} from '../../utils/meetingAudio';
const props=defineProps({agencyId:[Number,String],clientId:[Number,String],clinicalSessionId:[Number,String],officeEventId:[Number,String],baseUrl:{type:String,default:'/session-recordings/session'},apiClient:{type:Object,default:null}});
const emit=defineEmits(['narrative-ready','close']);
const defaultApi=ref(null);
const api=computed(()=>props.apiClient||defaultApi.value),state=ref(null),loading=ref(true),busy=ref(false),error=ref(''),hint=ref('');
const recording=computed(()=>state.value?.recording),allConsented=computed(()=>state.value?.participants?.length&&state.value.participants.every(p=>p.consented));
const context=()=>({agencyId:Number(props.agencyId),clientId:Number(props.clientId),...(props.clinicalSessionId?{clinicalSessionId:Number(props.clinicalSessionId)}:{}),...(props.officeEventId?{officeEventId:Number(props.officeEventId)}:{})});
const templateId=ref(''),additionalName=ref(''),additionalType=ref('adult'),agreement=ref(null),selectedParticipant=ref(null),agreementPdf=ref(''),signerUserId=ref(''),guardianSignerUserId=ref(''),signerName=ref(''),relationship=ref('self'),accepted=ref(false),signatureData=ref(''),authorityConfirmed=ref(false),allParticipantsListed=ref(false),authorityReviewed=ref(false),providerAgrees=ref(false),capturing=ref(false),narrative=ref(''),narrativeEdited=ref(false);
const guardianChoices=computed(()=>(selectedParticipant.value?.signers||[]).filter(s=>s.relationship!=='self'));
function selectGuardian(){signerName.value=guardianChoices.value.find(s=>Number(s.userId)===Number(guardianSignerUserId.value))?.name||'';}
let poller,stream,recorder,segmentTimer,segmentDone,queued=Promise.resolve(),queuedCount=0,disposed=false,discard=false;
const requestOptions={skipGlobalLoading:true,skipAuthRedirect:true};
function endpoint(suffix=''){return `${props.baseUrl}/${recording.value.id}${suffix}`;}
function message(e){return e.response?.data?.error?.message||e.message||'Unable to complete session recording.';}
async function load(){try{const {data}=await api.value.get(`${props.baseUrl}/context`,{...requestOptions,params:context()});if(disposed)return;state.value=data;if(!narrativeEdited.value&&data.recording?.narrative)narrative.value=data.recording.narrative;if(capturing.value&&(!data.ready||data.recording?.paused)){await stopCapture(true);hint.value='Recording paused because its consent or session permissions changed.';}}catch(e){error.value=message(e);if(capturing.value)await stopCapture(true);}finally{loading.value=false;}}
async function action(fn){busy.value=true;error.value='';try{await fn();}catch(e){error.value=message(e);}finally{busy.value=false;}}
async function setup(){await action(async()=>{const {data}=await api.value.post(`${props.baseUrl}/start-setup`,context(),requestOptions);state.value=data;});}
function resetConfirmation(){allParticipantsListed.value=false;authorityReviewed.value=false;providerAgrees.value=false;}
async function addParticipant(){await action(async()=>{await api.value.post(endpoint('/participants'),{name:additionalName.value,type:additionalType.value},requestOptions);additionalName.value='';resetConfirmation();await load();});}
async function remove(p){await action(async()=>{await api.value.post(endpoint('/participants'),{removeParticipantId:p.id},requestOptions);resetConfirmation();await load();});}
function closeWaiver(){agreement.value=null;selectedParticipant.value=null;if(agreementPdf.value)URL.revokeObjectURL(agreementPdf.value);agreementPdf.value='';signatureData.value='';}
async function openWaiver(p){await action(async()=>{closeWaiver();const {data}=await api.value.post(endpoint('/consent'),{participantId:p.id,templateId:Number(templateId.value)},requestOptions);selectedParticipant.value={...p,signers:data.signers||p.signers||[]};agreement.value=data;signerName.value='';relationship.value=p.requiresGuardian?'parent':'self';accepted.value=false;authorityConfirmed.value=false;signerUserId.value='';guardianSignerUserId.value='';if(data.templateType==='pdf'){const result=await api.value.get(endpoint(`/consent/${p.id}/pdf`),{...requestOptions,responseType:'blob'});agreementPdf.value=URL.createObjectURL(result.data);}resetConfirmation();await load();});}
async function signHere(){await action(async()=>{await api.value.post(endpoint(`/consent/${selectedParticipant.value.id}/sign`),{documentHash:agreement.value.documentHash,signerName:signerName.value,signerUserId:guardianSignerUserId.value?Number(guardianSignerUserId.value):null,relationship:relationship.value,accepted:accepted.value,signatureData:signatureData.value,presentedByClinician:true,signerPresent:true,authorityConfirmed:authorityConfirmed.value},requestOptions);closeWaiver();await load();});}
async function assignPortal(){await action(async()=>{await api.value.post(endpoint(`/consent/${selectedParticipant.value.id}/assign`),{signerUserId:Number(signerUserId.value)},requestOptions);closeWaiver();hint.value='Waiver assigned to the authorized portal recipient. Recording stays off until it is signed and this session is confirmed.';await load();});}
async function withdraw(p){await action(async()=>{await stopCapture(true);await api.value.post(endpoint(`/consent/${p.id}/withdraw`),{},requestOptions);resetConfirmation();await load();});}
async function confirm(){await action(async()=>{await api.value.post(endpoint('/confirm'),{allParticipantsListed:allParticipantsListed.value,consentAuthorityReviewed:authorityReviewed.value,providerAgreesToRecording:providerAgrees.value},requestOptions);await load();});}
function beginSegment(){if(disposed||!capturing.value||!stream)return;const type=['audio/webm;codecs=opus','audio/mp4','audio/ogg;codecs=opus'].find(t=>MediaRecorder.isTypeSupported(t));const active=new MediaRecorder(stream,type?{mimeType:type}:undefined),parts=[],revision=recording.value.revision,chunkKey=crypto.randomUUID();recorder=active;discard=false;segmentDone=new Promise(resolve=>{active.ondataavailable=e=>{if(e.data?.size)parts.push(e.data);};active.onstop=()=>{const drop=discard;recorder=null;const blob=new Blob(parts,{type:active.mimeType||type});if(!drop&&blob.size){queuedCount++;queued=queued.then(async()=>{const body=new FormData();body.append('audio',await meetingAudioWav(blob),'segment.wav');body.append('revision',String(revision));body.append('chunkKey',chunkKey);try{await api.value.post(endpoint('/audio'),body,{...requestOptions,timeout:120000});}catch(e){error.value=message(e);await stopCapture(true);void api.value.post(endpoint('/control'),{action:'pause'},requestOptions).catch(()=>{});}finally{queuedCount--;}});}resolve();if(capturing.value&&queuedCount>=3){capturing.value=false;stream?.getTracks().forEach(t=>t.stop());stream=null;hint.value='Recording paused while saved audio is processed. Resume explicitly after processing finishes.';void queued.then(async()=>{await api.value.post(endpoint('/control'),{action:'pause'},requestOptions);await load();}).catch(e=>error.value=message(e));}else if(capturing.value)beginSegment();};active.onerror=()=>{error.value='Microphone recording was interrupted. Reopen recording and confirm consent before resuming.';void pause();};});active.start();segmentTimer=setTimeout(()=>{if(active.state==='recording')active.stop();},10000);}
async function stopCapture(drop=false){capturing.value=false;discard=drop;clearTimeout(segmentTimer);if(recorder?.state==='recording'){const done=segmentDone;recorder.stop();await done;}stream?.getTracks().forEach(t=>t.stop());stream=null;}
async function start(){await action(async()=>{if(!navigator.mediaDevices?.getUserMedia||typeof MediaRecorder==='undefined')throw new Error('This device cannot capture session audio. Use a supported signed app or browser.');await api.value.post(endpoint('/control'),{action:recording.value.status==='setup'?'start':'resume'},requestOptions);await load();try{stream=await navigator.mediaDevices.getUserMedia({audio:true});capturing.value=true;beginSegment();hint.value='Recording is on. Keep this app open. Pause whenever someone enters or consent changes.';}catch(e){await api.value.post(endpoint('/control'),{action:'pause'},requestOptions);throw e;}});}
async function pause(){await action(async()=>{await stopCapture(false);await queued;await api.value.post(endpoint('/control'),{action:'pause'},requestOptions);await load();});}
async function finish(){await action(async()=>{await stopCapture(false);await queued;const {data}=await api.value.post(endpoint('/finish'),{}, {...requestOptions,timeout:300000});narrative.value=data.narrative;narrativeEdited.value=false;await load();});}
function useNarrative(){emit('narrative-ready',{narrative:narrative.value,recordingId:recording.value.id,clinicalSessionId:state.value.context.clinicalSessionId,officeEventId:state.value.context.officeEventId});}
function visibilityChanged(){if(document.visibilityState==='hidden'&&capturing.value){void stopCapture(true);void api.value.post(endpoint('/control'),{action:'pause'},requestOptions).catch(()=>{});hint.value='Recording paused while the app was in the background. Return and resume explicitly.';}}
onMounted(async()=>{if(!props.apiClient)defaultApi.value=(await import('../../services/api')).default;await load();if(disposed)return;poller=setInterval(()=>{if(!busy.value)void load();},7000);document.addEventListener('visibilitychange',visibilityChanged);});
onBeforeUnmount(()=>{disposed=true;clearInterval(poller);document.removeEventListener('visibilitychange',visibilityChanged);if(capturing.value){void stopCapture(true);void api.value.post(endpoint('/control'),{action:'pause'},requestOptions).catch(()=>{});}closeWaiver();});
defineExpose({load,pause});
</script>
<style scoped>
.session-capture{background:#fff;color:#163555;padding:clamp(16px,3vw,28px);border:1px solid #dce5ee;border-radius:18px;max-width:900px;margin:auto}.session-capture header{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}.session-capture h2{font-size:24px;margin:0 0 8px}.session-capture h3{margin:22px 0 8px}.session-capture p{line-height:1.55;color:#52677d}.privacy,.notice{background:#f4f7fc;border-left:3px solid #d7b454;padding:12px;font-size:13px}.participant{display:flex;gap:12px;align-items:center;justify-content:space-between;padding:15px 0;border-bottom:1px solid #e4ebf2}.participant small{display:block;color:#64788b;margin-top:5px}.participant-actions{display:flex;flex-wrap:wrap;gap:8px;justify-content:flex-end}.consent-state{display:inline-block;font-size:12px;background:#fff3d6;color:#70530d;padding:5px 8px;border-radius:6px;margin:6px 0}.consent-state.signed{background:#e6f4ed;color:#1a6549}.session-capture button{padding:10px 14px;border:1px solid #c7d6e5;border-radius:10px;background:#f5f8fc;color:#183f6c;font:inherit;cursor:pointer}.session-capture button:disabled{opacity:.5;cursor:default}.session-capture label{display:block;margin:12px 0;font-weight:600;font-size:14px}.session-capture input:not([type=checkbox]),.session-capture select,.session-capture textarea{display:block;width:100%;box-sizing:border-box;padding:12px;border:1px solid #cbd9e7;border-radius:8px;margin-top:7px;font:inherit;color:inherit;background:#fff}.session-capture .check{display:flex;gap:8px;align-items:flex-start;font-weight:400;line-height:1.5}.session-capture .check input{margin-top:4px}.add-participant,.session-capture fieldset{border:1px solid #dce5ee;padding:14px;border-radius:12px;margin:18px 0}.waiver{border:2px solid #b99b48;border-radius:12px;padding:14px;margin:20px 0}.waiver iframe{width:100%;height:350px;border:1px solid #dce5ee}.capture-controls{display:flex;align-items:center;flex-wrap:wrap;gap:10px;margin:20px 0}.capture-controls strong{flex:1 1 100%}.narrative-review{border-top:1px solid #dce5ee;padding-top:16px}[role=alert]{color:#a32828!important}@media(max-width:520px){.participant{display:block}.participant-actions{justify-content:flex-start;margin-top:7px}.session-capture{border-radius:0;padding:16px}}
</style>
